function renderSurpriseAdmin(){if(!el.surpriseAdminList)return;const list=liveState.surprises||[];el.surpriseAdminList.innerHTML=list.length?list.map(x=>`<div class="surprise-admin-row"><span><b>${esc(x.display_name||'Invitado')}</b><small>${esc(x.preference)} · ${esc(x.status)}</small></span><span class="surprise-admin-actions">${x.status==='pending'?`<button data-surprise-status="accepted" data-surprise-id="${x.id}">✓</button>`:''}<button data-surprise-status="completed" data-surprise-id="${x.id}">🎵</button><button data-surprise-status="rejected" data-surprise-id="${x.id}">×</button></span></div>`).join(''):'<div class="summary-empty">Sin solicitudes pendientes.</div>'}
function hubStatusPriority(s){return({playing:4,next:3,accepted:2,pending:1,played:0})[s]??0}
function renderMyPartyHub(activity={}){if(!el.myPartyHub)return;const nick=getGuestNickname?.()||'';el.myPartyHello.textContent=nick?`Hola, ${nick} 🔥`:'Hola 👋';el.myPartyEvent.textContent=currentEvent?.display_name||currentEvent?.name||'Tu fiesta';el.hubRequests.textContent=Number(activity.requests)||0;el.hubVotes.textContent=Number(activity.votes)||0;const defs=typeof achievementDefs!=='undefined'?achievementDefs:[],stats={requests:Number(activity.requests)||0,votes:Number(activity.votes)||0,played:Number(activity.played)||0},n=defs.filter(a=>{try{return a.test(stats)}catch{return false}}).length;el.hubAchievements.textContent=`${n}/${defs.length||6}`;el.hubPoints.textContent=el.gamePoints?.textContent||'0';el.myPartyLevel.textContent=el.gameLevel?.textContent?`🎧 ${el.gameLevel.textContent}`:'🎧 Invitado';const ids=new Set(getMySongIds()),mine=rows.filter(x=>ids.has(x.id)&&x.status!=='rejected').sort((a,b)=>hubStatusPriority(b.status)-hubStatusPriority(a.status)||b.votes-a.votes),song=mine[0];el.hubMySong.hidden=!song;if(song){const visual=song.artwork_url?`<img src="${esc(song.artwork_url)}" alt="">`:'<span class="hub-song-fallback">🎵</span>';el.hubMySong.innerHTML=`${visual}<span><b>${esc(song.title)}</b><small>${esc(song.artist||'Artista por confirmar')} · ♥ ${song.votes}</small></span><span class="hub-song-state ${esc(song.status)}">${labels[song.status]||song.status}</span>`}const actions=[];if(liveState.battle)actions.push({icon:'⚔️',title:'Batalla activa',meta:'Elige tu favorita',target:'battleGuestCard'});if(liveState.challenge)actions.push({icon:'⚡',title:'Reto activo',meta:`${liveState.challenge.current_value||0} / ${liveState.challenge.target_value||0}`,target:'challengeGuestCard'});if(!liveState.surprises?.some(x=>x.visitor_id===visitorToken&&['pending','accepted'].includes(x.status)))actions.push({icon:'🎁',title:'Sorpresa del DJ',meta:'Deja que el DJ elija por ti',target:'djSurpriseGuestCard'});if(!feedbackState.rating)actions.push({icon:'⭐',title:'Evalúa al DJ',meta:'Tu opinión ayuda a mejorar',target:'djFeedbackCard'});if(!actions.length)actions.push({icon:'🔥',title:'Sigue participando',meta:'Vota y ayuda a mover el ranking',target:'ranking'});el.hubActions.innerHTML=actions.slice(0,4).map(a=>`<button class="hub-action" type="button" data-hub-jump="${a.target}"><span><strong>${a.icon} ${esc(a.title)}</strong><small>${esc(a.meta)}</small></span><span class="arrow">›</span></button>`).join('')}
