function updateBadge(){el.newBadge.hidden=!unseen;el.newBadge.textContent=unseen>99?'99+':unseen;document.title=unseen?`(${unseen}) Pide Tu Tema | Luis DJ`:'Pide Tu Tema | Luis DJ'}
